import emoji

def parse_emojis(file_path):
    with open(file_path, 'r', encoding='utf-8') as file:
        data = file.read()

    parsed_emojis = []
    for char in data:
        if char in emoji.EMOJI_DATA:
            parsed_emojis.append(char)

    return parsed_emojis

def map_emojis_to_ascii(emojis):
    return [ord(emoji) for emoji in emojis]

def main():
    input_path = '/home/ctfplayer/ctf_files/emoji.txt'

    emojis = parse_emojis(input_path)
    ascii_values = map_emojis_to_ascii(emojis)
    print("Parsed Emojis:", emojis)
    print("ASCII Values:", ascii_values)

if __name__ == "__main__":
    main()

